const isInvalidOrPlaceholder = (val: string | undefined | null): boolean => {
  if (!val) return true;
  const clean = val.trim().toLowerCase();
  return clean === "" || 
         clean === "not set" || 
         clean === "undefined" || 
         clean === "null" ||
         clean.includes("select ") ||
         clean.includes("choose ") ||
         clean === "select" ||
         clean === "choose" ||
         clean === "not completed";
};

const TournamentCountdown = ({ tournament }: { tournament: any }) => {
  const [timeLeft, setTimeLeft] = useState({ days: 0, hours: 0, minutes: 0, seconds: 0 });
  const [statusState, setStatusState] = useState<'countdown' | 'live' | 'ended'>('countdown');

  useEffect(() => {
    const calculateTimeLeft = () => {
      if (!tournament) return;
      
      if (tournament.status === 'Ended') {
        setStatusState('ended');
        return;
      }

      let targetDate: Date | null = null;
      
      // Resolve Year, Month, Day first
      let year = new Date().getFullYear();
      let month = new Date().getMonth(); // 0-indexed
      let day = new Date().getDate();

      // Attempt 1: Parse from tournament ID if present: e.g. ff_20260601...
      if (tournament.id) {
        // Look for 8 digits of date in ID
        const dateInIdMatch = tournament.id.match(/_(\d{8})/);
        if (dateInIdMatch) {
          const dateStr = dateInIdMatch[1];
          year = parseInt(dateStr.substring(0, 4), 10);
          month = parseInt(dateStr.substring(4, 6), 10) - 1;
          day = parseInt(dateStr.substring(6, 8), 10);
        } else {
          // Fallback if no prefix underscore, for raw IDs like "ff20260601..."
          const rawDateMatch = tournament.id.match(/(\d{8})/);
          if (rawDateMatch) {
            const dateStr = rawDateMatch[1];
            year = parseInt(dateStr.substring(0, 4), 10);
            month = parseInt(dateStr.substring(4, 6), 10) - 1;
            day = parseInt(dateStr.substring(6, 8), 10);
          }
        }
      }

      // Attempt 2: Override Date if time field contains explicit parenthesized ISO date
      if (tournament.time) {
        const dateMatch = tournament.time.match(/\((\d{4})-(\d{2})-(\d{2})\)/);
        if (dateMatch) {
          year = parseInt(dateMatch[1], 10);
          month = parseInt(dateMatch[2], 10) - 1;
          day = parseInt(dateMatch[3], 10);
        } else if (tournament.time.toLowerCase().includes('tomorrow')) {
          const tomorrow = new Date();
          tomorrow.setDate(tomorrow.getDate() + 1);
          year = tomorrow.getFullYear();
          month = tomorrow.getMonth();
          day = tomorrow.getDate();
        }
      }

      // Resolve Hour and Minute
      let hour = 21;
      let minute = 30;
      let resolvedTime = false;

      if (tournament.time) {
        // Matches e.g. "9:30 PM", "09:30 PM", "11:00 am", "5:00 PM" with single/double digit hours
        const ampmMatch = tournament.time.match(/(\d{1,2}):(\d{2})\s*(AM|PM|am|pm)/i);
        if (ampmMatch) {
          hour = parseInt(ampmMatch[1], 10);
          minute = parseInt(ampmMatch[2], 10);
          const ampm = ampmMatch[3].toUpperCase();
          if (ampm === 'PM' && hour < 12) hour += 12;
          if (ampm === 'AM' && hour === 12) hour = 0;
          resolvedTime = true;
        } else {
          // 24-hour match e.g. "21:30" or "09:30"
          const h24Match = tournament.time.match(/(\d{1,2}):(\d{2})/);
          if (h24Match) {
            hour = parseInt(h24Match[1], 10);
            minute = parseInt(h24Match[2], 10);
            if (hour < 12 && (tournament.time.toLowerCase().includes('tonight') || tournament.time.toLowerCase().includes('pm') || tournament.time.toLowerCase().includes('night'))) {
              hour += 12;
            }
            resolvedTime = true;
          }
        }
      }

      // Attempt 3: If not resolved yet, extract of startTimeISO
      if (!resolvedTime && tournament.startTimeISO) {
        const parts = tournament.startTimeISO.match(/T(\d{2}):(\d{2})/);
        if (parts) {
          hour = parseInt(parts[1], 10);
          minute = parseInt(parts[2], 10);
          resolvedTime = true;
        }
      }

      // Attempt 4: If still not resolved, parse from tournament ID time section (e.g. key _2026060121301)
      if (!resolvedTime && tournament.id) {
        const idTimeMatch = tournament.id.match(/_(\d{8})(\d{4})/);
        if (idTimeMatch) {
          const timePart = idTimeMatch[2];
          hour = parseInt(timePart.substring(0, 2), 10);
          minute = parseInt(timePart.substring(2, 4), 10);
          resolvedTime = true;
        }
      }

      // Instantiating local timezone Date object manually which is 100% browser/OS consistent
      targetDate = new Date(year, month, day, hour, minute, 0);

      if (isNaN(targetDate.getTime())) {
        const baseTime = tournament.updatedAt?.seconds 
          ? new Date(tournament.updatedAt.seconds * 1000) 
          : (tournament.updatedAt ? new Date(tournament.updatedAt) : new Date());
        targetDate = new Date(baseTime.getTime() + 3 * 60 * 60 * 1000);
      }

      const now = Date.now();
      // Bumping strategy for open/active tournaments which are in the past to ensure a valid live countdown is shown
      if (targetDate.getTime() <= now && tournament.status !== 'Ended') {
        const todayObj = new Date();
        const curYear = todayObj.getFullYear();
        const curMonth = todayObj.getMonth();
        const curDay = todayObj.getDate();
        
        // Reset to today with the correct hour and minute
        let projectedDate = new Date(curYear, curMonth, curDay, hour, minute, 0);
        
        // If that is still in the past, reset to tomorrow
        if (projectedDate.getTime() <= now) {
          const tomorrowObj = new Date();
          tomorrowObj.setDate(tomorrowObj.getDate() + 1);
          projectedDate = new Date(tomorrowObj.getFullYear(), tomorrowObj.getMonth(), tomorrowObj.getDate(), hour, minute, 0);
        }
        targetDate = projectedDate;
      }

      const diff = targetDate.getTime() - now;

      if (diff <= 0) {
        setStatusState('live');
        return;
      }

      setStatusState('countdown');

      const days = Math.floor(diff / (1000 * 60 * 60 * 24));
      const hours = Math.floor((diff / (1000 * 60 * 60)) % 24);
      const minutes = Math.floor((diff / 1000 / 60) % 60);
      const seconds = Math.floor((diff / 1000) % 60);

      setTimeLeft({ days, hours, minutes, seconds });
    };

    calculateTimeLeft();
    const interval = setInterval(calculateTimeLeft, 1000);
    return () => clearInterval(interval);
  }, [tournament]);

  if (statusState === 'ended') {
    return (
      <div className="flex items-center gap-1.5 bg-slate-800/80 border border-slate-700/60 px-3.5 py-1.5 rounded-2xl text-slate-400 font-mono text-xs font-black tracking-wider uppercase shadow-md select-none">
        <span className="h-2 w-2 rounded-full bg-slate-500"></span>
        <span>Match Ended</span>
      </div>
    );
  }

  if (statusState === 'live') {
    return (
      <div className="flex items-center gap-1.5 bg-red-500/15 border border-red-500/35 px-3.5 py-1.5 rounded-2xl text-red-500 font-mono text-xs font-black tracking-wider uppercase shadow-[0_0_15px_rgba(239,68,68,0.22)] select-none">
        <Clock className="h-4 w-4 animate-spin shrink-0 text-red-500" />
        <div className="flex items-center gap-1">
          {timeLeft.days > 0 && (
            <>
              <span>{timeLeft.days}d</span>
              <span className="text-[10px] text-red-400">:</span>
            </>
          )}
          <span>{String(timeLeft.hours).padStart(2, '0')}h</span>
          <span className="text-[10px] text-red-400">:</span>
          <span>{String(timeLeft.minutes).padStart(2, '0')}m</span>
          <span className="text-[10px] text-red-400">:</span>
          <span className="text-red-400 font-mono font-black">{String(timeLeft.seconds).padStart(2, '0')}s</span>
        </div>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-1.5 bg-amber-500/10 border border-amber-500/35 px-3.5 py-1.5 rounded-2xl text-amber-400 font-mono text-xs font-black tracking-wider shadow-[0_0_15px_rgba(245,158,11,0.1)] select-none">
      <Clock className="h-4 w-4 animate-pulse shrink-0 text-amber-400" />
      <div className="flex items-center gap-1">
        {timeLeft.days > 0 && (
          <>
            <span>{timeLeft.days}d</span>
            <span className="text-[10px] text-slate-500">:</span>
          </>
        )}
        <span>{String(timeLeft.hours).padStart(2, '0')}h</span>
        <span className="text-[10px] text-slate-500">:</span>
        <span>{String(timeLeft.minutes).padStart(2, '0')}m</span>
        <span className="text-[10px] text-slate-500">:</span>
        <span className="text-orange-500 font-mono font-black">{String(timeLeft.seconds).padStart(2, '0')}s</span>
      </div>



    </div>
  );
};

const isMatchOlderThanAWeek = (match: any) => {
  if (!match) return false;
  if (match.status !== 'Ended') return false;
  
  let matchDate: Date | null = null;
  if (match.startTimeISO) {
    matchDate = new Date(match.startTimeISO);
  } else if (match.updatedAt) {
    if (typeof match.updatedAt.toDate === 'function') {
      matchDate = match.updatedAt.toDate();
    } else {
      matchDate = new Date(match.updatedAt);
    }
  }
  
  if (!matchDate || isNaN(matchDate.getTime())) {
    return false;
  }
  
  const oneWeekAgo = new Date();
  oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
  return matchDate < oneWeekAgo;
};

