  const handleClearUpcomingOngoingMatches = async () => {
    setIsClearingMatches(true);
    setClearingMatchesMessage('Finding upcoming and ongoing matches...');
    try {
      let deletedCount = 0;
      const collectionsToClean = ['tournaments_freefire', 'tournaments_pubg', 'tournaments_ludo'];

      for (const colName of collectionsToClean) {
        const snap = await getDocs(collection(db, colName));
        for (const docSnap of snap.docs) {
          if (!docSnap.exists()) continue;
          const data = docSnap.data();
          const s = String(data.status || '').trim().toLowerCase();
          
          // upcoming or ongoing: open, upcoming, ongoing, live, or empty
          const isUpcomingOrOngoing = 
            s === 'open' || 
            s === 'upcoming' || 
            s === 'ongoing' || 
            s === 'live' || 
            !s;

          if (isUpcomingOrOngoing) {
            await deleteDoc(doc(db, colName, docSnap.id));
            deletedCount++;
          }
        }
      }
      setClearingMatchesMessage(`Successfully deleted ${deletedCount} matches!`);
      setTimeout(() => {
        setClearingMatchesMessage(null);
        setShowClearMatchesConfirm(false);
      }, 3000);
    } catch (err: any) {
      console.error('Error clearing matches:', err);
      setClearingMatchesMessage(`Error: ${err.message || err}`);
    } finally {
      setIsClearingMatches(false);
    }
  };
  
