  const [allUserTokenTransactions, setAllUserTokenTransactions] = useState<any[]>([]);

  const getTxTimeMs = (tx: any): number => {
    if (!tx) return 0;
    // 1. Firestore Timestamp
    if (tx.createdAt?.seconds) {
      return tx.createdAt.seconds * 1000 + (tx.createdAt.nanoseconds ? tx.createdAt.nanoseconds / 1000000 : 0);
    }
    if (tx.createdAt?.toMillis && typeof tx.createdAt.toMillis === 'function') {
      return tx.createdAt.toMillis();
    }
    // 2. ISO / parseable date string
    if (typeof tx.createdAt === 'string') {
      const t = new Date(tx.createdAt).getTime();
      if (!isNaN(t)) return t;
    }
    // 3. Numeric timestamp
    if (typeof tx.timestamp === 'number') {
      return tx.timestamp;
    }
    if (tx.timestamp?.seconds) {
      return tx.timestamp.seconds * 1000;
    }
    if (typeof tx.timestamp === 'string') {
      const t = new Date(tx.timestamp).getTime();
      if (!isNaN(t)) return t;
    }
    if (typeof tx.date === 'string') {
      const t = new Date(tx.date).getTime();
      if (!isNaN(t)) return t;
    }
    return 0;
  };

  const handleUserHistoryPageChange = (newPage: number) => {
    const targetPage = newPage < 1 ? 1 : newPage;
    if (allUserTokenTransactions.length > 0) {
      const startIndex = (targetPage - 1) * 10;
      const pageItems = allUserTokenTransactions.slice(startIndex, startIndex + 10);
      const hasMore = allUserTokenTransactions.length > (targetPage * 10);
      setTokenTransactions(pageItems);
      setUserHistoryPage(targetPage);
      setUserHistoryHasMore(hasMore);
    } else {
      fetchTokenTransactions(targetPage);
    }
  };

  const fetchTokenTransactions = async (page: number = 1) => {
    if (!user) return;
    setUserHistoryLoading(true);
    const targetPage = page < 1 ? 1 : page;
    try {
      const txRef = collection(db, 'users', user.uid, 'tokenTransactions');
      const snap = await getDocs(txRef);
      const txList: any[] = [];
      snap.forEach(d => txList.push({ id: d.id, ...d.data() }));

      // Strictly sort descending by true normalized timestamp: newest on top
      txList.sort((a, b) => getTxTimeMs(b) - getTxTimeMs(a));

      setAllUserTokenTransactions(txList);

      const startIndex = (targetPage - 1) * 10;
      const pageItems = txList.slice(startIndex, startIndex + 10);
      const hasMore = txList.length > (targetPage * 10);

      setTokenTransactions(pageItems);
      setUserHistoryPage(targetPage);
      setUserHistoryHasMore(hasMore);
    } catch (err) {
      console.error("Error fetching transactions", err);
    } finally {
      setUserHistoryLoading(false);
    }
  };

  const handleVerifySendTokens = async () => {
    if (!user) {
      setSendError("Please sign in first to transfer tokens.");
      return;
    }
    const playvearIdToFind = sendEmail.trim();
    const amountVal = Number(sendAmount);
    
    if (!playvearIdToFind) {
      setSendError("Recipient's PlayVear ID is required.");
      return;
    }
    if (playvearIdToFind === userProfile?.playvearId) {
      setSendError("You cannot send tokens to yourself!");
      return;
    }
    if (isNaN(amountVal) || amountVal <= 0) {
      setSendError("Please specify a valid token transfer amount.");
      return;
    }
    if (tokens < amountVal) {
      setSendError(`Insufficient tokens! You have ${Number(tokens).toFixed(2)} tokens, but tried sending ${amountVal}.`);
      return;
    }

    setSendLoading(true);
    setSendSuccess(null);
    setSendError(null);

    try {
      const usersCol = collection(db, 'users');
      const q = query(usersCol, where('playvearId', '==', playvearIdToFind));
      const qSnap = await getDocs(q);

      if (qSnap.empty) {
        setSendError(`No account found for PlayVear ID "${playvearIdToFind}". Please check the ID!`);
        setSendLoading(false);
        return;
      }

      const friendDoc = qSnap.docs[0];
      const friendData = friendDoc.data();

      setTokenTransferConfirmData({
        friendId: friendDoc.id,
        friendData,
        amountVal,
        playvearIdToFind
      });

    } catch (err) {
      console.error("Verification error:", err);
      setSendError("Verification failed. Please try again.");
    } finally {
      setSendLoading(false);
    }
  };

  const handleConfirmSendTokens = async () => {
    if (!tokenTransferConfirmData || !user) return;
    
    setSendLoading(true);
    setSendSuccess(null);
    setSendError(null);

    const { friendId, friendData, amountVal, playvearIdToFind } = tokenTransferConfirmData;
    
    (window as any).runWithProgress("Transferring Tokens", async () => {
      try {
        const friendCurrentTokens = typeof friendData.tokens === 'number' ? friendData.tokens : 0;
        
        const recipientDocRef = doc(db, 'users', friendId);
        const senderDocRef = doc(db, 'users', user.uid);

        const nextSenderTokens = tokens - amountVal;
        await updateDoc(senderDocRef, {
          tokens: nextSenderTokens,
          updatedAt: serverTimestamp()
        });

        await updateDoc(recipientDocRef, {
          tokens: friendCurrentTokens + amountVal,
          updatedAt: serverTimestamp()
        });
        
        // Save Transaction for Sender
        await addDoc(collection(db, 'users', user.uid, 'tokenTransactions'), {
          type: 'sent',
          amount: amountVal,
          otherUserEmail: playvearIdToFind,
          otherUserName: friendData.displayName || 'Unknown',
          createdAt: serverTimestamp()
        });

        // Save Transaction for Recipient
        await addDoc(collection(db, 'users', friendId, 'tokenTransactions'), {
          type: 'received',
          amount: amountVal,
          otherUserEmail: userProfile?.playvearId || user.uid,
          otherUserName: userProfile?.displayName || user.displayName || 'Unknown',
          createdAt: serverTimestamp()
        });

        // Notify Recipient
        await addDoc(collection(db, 'users', friendId, 'notifications'), {
          title: '🪙 Tokens Received!',
          message: `You have received ${amountVal} Tokens from ${userProfile?.displayName || 'PlayVear Gamer'} (PlayVear ID: ${userProfile?.playvearId || 'N/A'}).`,
          type: 'token_received',
          isRead: false,
          createdAt: serverTimestamp()
        });

        setTokensState(nextSenderTokens);
        setSendSuccess(`Success! Transferred 🪙 ${amountVal} Tokens to ${friendData.displayName || playvearIdToFind} successfully.`);
        setSendEmail('');
        setSendAmount('');
        setTokenTransferConfirmData(null);
        setTimeout(() => {
           setSendSuccess(null);
        }, 5000);
        
        // Refresh transactions if in history
        fetchTokenTransactions();

        try {
          localStorage.setItem(`vortex_tokens_${user.uid}`, String(nextSenderTokens));
        } catch (locErr) {
          console.error(locErr);
        }
      } catch (err) {
        console.error("Transfer token error:", err);
        setSendError("Transaction failed. Contact support if tokens were deducted.");
      }
    }).finally(() => {
      setSendLoading(false);
    });
  };

  const [leaderboardUsers, setLeaderboardUsers] = useState<any[]>([]);
  const [selectedLeaderboardDivision, setSelectedLeaderboardDivision] = useState<string>('all');
