  // Firestore subscription for Teams list
  useEffect(() => {
    const teamsCol = collection(db, 'teams');
    const unsubscribeTeams = onSnapshot(teamsCol, (snapshot) => {
      const list: any[] = [];
      snapshot.forEach((doc) => {
        list.push({ id: doc.id, ...doc.data() });
      });
      setAllTeamsList(list);
    }, (err) => {
      console.warn('Teams sync error:', err);
    });

    return () => unsubscribeTeams();
  }, []);

  const processedLeaderboard = useMemo(() => {
    // Filter active profiles (exclude sandbox or non-registered data)
    let list = leaderboardUsers.filter(p => p && (p.displayName || p.userId));

    // Apply Location filters
    if (selectedLeaderboardDivision && selectedLeaderboardDivision !== 'all') {
      list = list.filter(p => p.division === selectedLeaderboardDivision);
    }
    if (selectedLeaderboardDistrict && selectedLeaderboardDistrict !== 'all') {
      list = list.filter(p => p.district === selectedLeaderboardDistrict);
    }
    if (selectedLeaderboardUpazila && selectedLeaderboardUpazila !== 'all') {
      list = list.filter(p => p.upazila === selectedLeaderboardUpazila);
    }

    // Sort list based on the new ranking logic:
    // Aggregating from: Solo BR (soloStats), Squad BR (squadStats), Squad CS (squadCsStats)
    // 1. Total Kills (Primary)
    // 2. Matches Played
    // 3. Wins
    // 4. Booyah obtained
    // 5. Damage dealt
    list.sort((a, b) => {
      const getAggregated = (player: any) => {
        const s = player.soloStats || {};
        const sq = player.squadStats || {};
        const scs = player.squadCsStats || {};
        
        return {
          kills: (Number(s.kills) || 0) + (Number(sq.kills) || 0) + (Number(scs.kills) || 0),
          matches: (Number(s.matches) || 0) + (Number(sq.matches) || 0) + (Number(scs.matches) || 0),
          wins: (Number(s.wins) || 0) + (Number(sq.wins) || 0) + (Number(scs.wins) || 0),
          booyahs: (Number(s.booyahs) || 0) + (Number(sq.booyahs) || 0) + (Number(scs.booyahs) || 0),
          damage: (Number(s.damage) || 0) + (Number(sq.damage) || 0) + (Number(scs.damage) || 0)
        };
      };

      const aStats = getAggregated(a);
      const bStats = getAggregated(b);

      if (bStats.kills !== aStats.kills) return bStats.kills - aStats.kills;
      if (bStats.matches !== aStats.matches) return bStats.matches - aStats.matches;
      if (bStats.wins !== aStats.wins) return bStats.wins - aStats.wins;
      if (bStats.booyahs !== aStats.booyahs) return bStats.booyahs - aStats.booyahs;
      return bStats.damage - aStats.damage;
    });

    // Limit to top 10 players and attach aggregated display stats
    return list.slice(0, 10).map((p, index) => {
      const s = p.soloStats || {};
      const sq = p.squadStats || {};
      const scs = p.squadCsStats || {};

      return {
        ...p,
        calculatedRank: index + 1,
        displayKills: (Number(s.kills) || 0) + (Number(sq.kills) || 0) + (Number(scs.kills) || 0),
        displayMatches: (Number(s.matches) || 0) + (Number(sq.matches) || 0) + (Number(scs.matches) || 0),
        displayWins: (Number(s.wins) || 0) + (Number(sq.wins) || 0) + (Number(scs.wins) || 0),
        displayBooyahs: (Number(s.booyahs) || 0) + (Number(sq.booyahs) || 0) + (Number(scs.booyahs) || 0),
        displayDamage: (Number(s.damage) || 0) + (Number(sq.damage) || 0) + (Number(scs.damage) || 0)
      };
    });
  }, [leaderboardUsers, selectedLeaderboardDivision, selectedLeaderboardDistrict, selectedLeaderboardUpazila]);

  const SOLO_PER_PAGE = 10;
  const totalSoloPages = useMemo(() => {
    return Math.ceil(processedLeaderboard.length / SOLO_PER_PAGE) || 1;
  }, [processedLeaderboard]);

  const paginatedSoloLeaderboard = useMemo(() => {
    const startIdx = (soloLeaderboardPage - 1) * SOLO_PER_PAGE;
    return processedLeaderboard.slice(startIdx, startIdx + SOLO_PER_PAGE);
  }, [processedLeaderboard, soloLeaderboardPage]);

  const processedSquadLeaderboard = useMemo(() => {
    const mapOfTeams = new Map();
    (allTeamsList || []).forEach(t => {
      if (t && (t.name || t.id)) {
        mapOfTeams.set(t.id || t.name, t);
      }
    });

    let list = Array.from(mapOfTeams.values());

    // Apply Location filters for squad
    if (selectedSquadDivision && selectedSquadDivision !== 'all') {
      list = list.filter(s => s.division === selectedSquadDivision);
    }
    if (selectedSquadDistrict && selectedSquadDistrict !== 'all') {
      list = list.filter(s => s.district === selectedSquadDistrict);
    }
    if (selectedSquadUpazila && selectedSquadUpazila !== 'all') {
      list = list.filter(s => s.upazila === selectedSquadUpazila);
    }

    // Sort list
    list.sort((a, b) => {
      const aPoints = typeof a.points === 'number' ? a.points : 100;
      const bPoints = typeof b.points === 'number' ? b.points : 100;
      const aBooyahs = typeof a.booyahs === 'number' ? a.booyahs : 0;
      const bBooyahs = typeof b.booyahs === 'number' ? b.booyahs : 0;
      const aKills = typeof a.totalKills === 'number' ? a.totalKills : 0;
      const bKills = typeof b.totalKills === 'number' ? b.totalKills : 0;
      const aEco = typeof a.economyScore === 'number' ? a.economyScore : 50;
      const bEco = typeof b.economyScore === 'number' ? b.economyScore : 50;

      const aOverall = aPoints + (aBooyahs * 50) + (aKills * 5) + aEco;
      const bOverall = bPoints + (bBooyahs * 50) + (bKills * 5) + bEco;

      if (selectedSquadMetric === 'overall') {
        if (bOverall !== aOverall) return bOverall - aOverall;
        return bPoints - aPoints;
      } else if (selectedSquadMetric === 'points') {
        if (bPoints !== aPoints) return bPoints - aPoints;
        return bBooyahs - aBooyahs;
      } else if (selectedSquadMetric === 'booyahs') {
        if (bBooyahs !== aBooyahs) return bBooyahs - aBooyahs;
        return bKills - aKills;
      } else if (selectedSquadMetric === 'kills') {
        if (bKills !== aKills) return bKills - aKills;
        return bPoints - aPoints;
      } else if (selectedSquadMetric === 'economy') {
        if (bEco !== aEco) return bEco - aEco;
        return bPoints - aPoints;
      }
      return 0;
    });

    return list.slice(0, 12).map((squad, index) => ({
      ...squad,
      calculatedRank: index + 1
    }));
  }, [allTeamsList, selectedSquadDivision, selectedSquadDistrict, selectedSquadUpazila, selectedSquadMetric]);
  const [newTourneyGrandmasterOnly, setNewTourneyGrandmasterOnly] = useState<boolean>(false);
