  const [userTeams, setUserTeams] = useState<any[]>([]);
  const [pendingSquadJoinTourney, setPendingSquadJoinTourney] = useState<any>(null);
  const [isJoiningSquadTourney, setIsJoiningSquadTourney] = useState(false);
  const [squadJoinError, setSquadJoinError] = useState<string | null>(null);
  const [squadJoinSuccess, setSquadJoinSuccess] = useState<string | null>(null);

  const handleConfirmSquadJoinFromProfile = async (tournament: any) => {
    if (!user || !userProfile || !tournament) return;
    setIsJoiningSquadTourney(true);
    setSquadJoinError(null);
    setSquadJoinSuccess(null);

    const createdTeams = userTeams.filter(t => t.leaderId === user?.uid || t.leaderEmail?.toLowerCase() === user?.email?.toLowerCase());
    const squadToJoin = createdTeams[0] || userTeam || userTeams[0];

    if (!squadToJoin || !squadToJoin.name) {
      setSquadJoinError('No squad found. Please assemble a squad first.');
      setIsJoiningSquadTourney(false);
      return;
    }

    const entryFee = Number(tournament.entryFee) || 0;
    if (tokens < entryFee) {
      setSquadJoinError(`Insufficient tokens! Needed: ${entryFee} tokens, balance: ${Number(tokens).toFixed(2)} tokens.`);
      setIsJoiningSquadTourney(false);
      return;
    }

    try {
      await runTransaction(db, async (transaction) => {
        const tourneyRef = doc(db, 'tournaments_freefire', tournament.id);
        const tourneySnap = await transaction.get(tourneyRef);

        if (!tourneySnap.exists()) {
          throw new Error('Tournament no longer exists.');
        }

        const currentTourney = tourneySnap.data();
        const joinedSquads = currentTourney.joinedSquads || [];
        const maxSquads = currentTourney.maxSquads || 8;

        if (joinedSquads.length >= maxSquads) {
          throw new Error('Tournament squad slots are full!');
        }

        const userEmailNorm = (userProfile.email || user.email || '').trim().toLowerCase();
        const userIdNorm = userProfile.userId || user.uid;
        const squadNameNorm = (squadToJoin.name || '').trim().toLowerCase();

        // Check collision
        for (const existingSquad of joinedSquads) {
          const exNameNorm = (existingSquad.squadName || existingSquad.name || '').trim().toLowerCase();
          const exLeaderId = existingSquad.leaderId;
          const exLeaderEmail = (existingSquad.leaderEmail || '').trim().toLowerCase();

          const isSameSquad = (squadNameNorm && exNameNorm === squadNameNorm) ||
                              (exLeaderId && (exLeaderId === userIdNorm || exLeaderId === userProfile.userId)) ||
                              (exLeaderEmail && exLeaderEmail === userEmailNorm);

          if (isSameSquad) {
            throw new Error('Your squad is already registered for this tournament!');
          }
        }

        const isSquadAdminOrHost = userProfile?.role === 'admin' || userProfile?.role === 'sub_admin' || currentTourney.hostId === (userProfile?.userId || user?.uid) || (currentTourney.coHostIds && currentTourney.coHostIds.includes(userProfile?.userId || user?.uid));

        // 2. Specific Location Restriction Check
        if (currentTourney.locationRestrictionType) {
          if (currentTourney.locationRestrictionType === 'specific_division') {
            if (!userProfile.division || userProfile.division.trim().toLowerCase() !== (currentTourney.allowedDivision || '').trim().toLowerCase()) {
              throw new Error(`This tournament is restricted to squads from ${currentTourney.allowedDivision || 'specific'} Division. Your location (${userProfile.division || 'Not set'}) does not match.`);
            }
          } else if (currentTourney.locationRestrictionType === 'specific_district') {
            if (!userProfile.district || userProfile.district.trim().toLowerCase() !== (currentTourney.allowedDistrict || '').trim().toLowerCase()) {
              throw new Error(`This tournament is restricted to squads from ${currentTourney.allowedDistrict || 'specific'} District. Your location (${userProfile.district || 'Not set'}) does not match.`);
            }
          } else if (currentTourney.locationRestrictionType === 'specific_upazila') {
            if (!userProfile.upazila || userProfile.upazila.trim().toLowerCase() !== (currentTourney.allowedUpazila || '').trim().toLowerCase()) {
              throw new Error(`This tournament is restricted to squads from ${currentTourney.allowedUpazila || 'specific'} Upazila. Your location (${userProfile.upazila || 'Not set'}) does not match.`);
            }
          }
        }

        // 3. Regional representation check (excluding own squad)
        const rule = currentTourney.representationRule;

        if (rule && rule !== 'any') {
          if (rule === 'one_squad_per_upazila' || rule === 'one_player_per_upazila') {
            if (!userProfile.upazila || !userProfile.upazila.trim()) {
              throw new Error('Please set your Upazila in your Profile before joining this tournament.');
            }
            const normalizedUpa = userProfile.upazila.trim().toLowerCase();
            const otherSquadsInUpazila = joinedSquads.filter((s: any) => {
              const exNameNorm = (s.squadName || s.name || '').trim().toLowerCase();
              const exLeaderId = s.leaderId;
              const exLeaderEmail = (s.leaderEmail || '').trim().toLowerCase();
              const isSameSquad = (squadNameNorm && exNameNorm === squadNameNorm) || 
                                  (exLeaderId && (exLeaderId === userIdNorm || exLeaderId === userProfile.userId)) ||
                                  (exLeaderEmail && exLeaderEmail === userEmailNorm);
              return !isSameSquad;
            });

            const upazilaTaken = otherSquadsInUpazila.some((s: any) => s.upazila && s.upazila.trim().toLowerCase() === normalizedUpa) ||
                                 (currentTourney.registeredUpazilas || []).some((u: string) => u.trim().toLowerCase() === normalizedUpa);
            if (upazilaTaken) {
              throw new Error(`Someone has already joined from your Sub-district/Upazila (${userProfile.upazila}), and you cannot join. Only 1 squad per Upazila is allowed.`);
            }
          } else if (rule === 'one_squad_per_district' || rule === 'one_player_per_district') {
            if (!userProfile.district || !userProfile.district.trim()) {
              throw new Error('Please set your District in your Profile before joining this tournament.');
            }
            const normalizedDist = userProfile.district.trim().toLowerCase();
            const otherSquadsInDistrict = joinedSquads.filter((s: any) => {
              const exNameNorm = (s.squadName || s.name || '').trim().toLowerCase();
              const exLeaderId = s.leaderId;
              const exLeaderEmail = (s.leaderEmail || '').trim().toLowerCase();
              const isSameSquad = (squadNameNorm && exNameNorm === squadNameNorm) || 
                                  (exLeaderId && (exLeaderId === userIdNorm || exLeaderId === userProfile.userId)) ||
                                  (exLeaderEmail && exLeaderEmail === userEmailNorm);
              return !isSameSquad;
            });

            const districtTaken = otherSquadsInDistrict.some((s: any) => s.district && s.district.trim().toLowerCase() === normalizedDist) ||
                                  (currentTourney.registeredDistricts || []).some((d: string) => d.trim().toLowerCase() === normalizedDist);
            if (districtTaken) {
              throw new Error(`Someone has already joined from your District (${userProfile.district}), and you cannot join. Only 1 squad per District is allowed.`);
            }
          } else if (rule === 'one_squad_per_division' || rule === 'one_player_per_division') {
            if (!userProfile.division || !userProfile.division.trim()) {
              throw new Error('Please set your Division in your Profile before joining this tournament.');
            }
            const normalizedDiv = userProfile.division.trim().toLowerCase();
            const otherSquadsInDivision = joinedSquads.filter((s: any) => {
              const exNameNorm = (s.squadName || s.name || '').trim().toLowerCase();
              const exLeaderId = s.leaderId;
              const exLeaderEmail = (s.leaderEmail || '').trim().toLowerCase();
              const isSameSquad = (squadNameNorm && exNameNorm === squadNameNorm) || 
                                  (exLeaderId && (exLeaderId === userIdNorm || exLeaderId === userProfile.userId)) ||
                                  (exLeaderEmail && exLeaderEmail === userEmailNorm);
              return !isSameSquad;
            });

            const divisionTaken = otherSquadsInDivision.some((s: any) => s.division && s.division.trim().toLowerCase() === normalizedDiv) ||
                                 (currentTourney.registeredDivisions || []).some((v: string) => v.trim().toLowerCase() === normalizedDiv);
            if (divisionTaken) {
              throw new Error(`Someone has already joined from your Division (${userProfile.division}), and you cannot join. Only 1 squad per Division is allowed.`);
            }
          }
        }

        // Deduct entry fee from captain's wallet
        if (entryFee > 0) {
          const userRef = doc(db, 'users', userProfile.userId || user.uid);
          const userSnap = await transaction.get(userRef);
          if (userSnap.exists()) {
            const userTokens = userSnap.data().tokens || 0;
            if (userTokens < entryFee) {
              throw new Error(`Insufficient tokens! Needed: ${entryFee}`);
            }
            transaction.update(userRef, {
              tokens: userTokens - entryFee,
              updatedAt: new Date().toISOString()
            });

            const historyRef = doc(collection(db, 'wallet_history'));
            transaction.set(historyRef, {
              userId: userProfile.userId || user.uid,
              userName: userProfile.displayName || 'Captain',
              type: 'debit',
              amount: entryFee,
              balanceAfter: userTokens - entryFee,
              description: `Tournament Entry Fee (${tournament.title})`,
              createdAt: serverTimestamp()
            });
          }
        }

        // Register squad
        const newSquadEntry = {
          id: `SQD-${Date.now()}`,
          name: squadToJoin.name,
          squadName: squadToJoin.name,
          logoUrl: squadToJoin.logoUrl || squadToJoin.coverUrl || null,
          coverUrl: squadToJoin.coverUrl || null,
          leaderId: userProfile.userId || user.uid,
          leaderName: userProfile.displayName || squadToJoin.leaderName || 'Captain',
          leaderEmail: userProfile.email || user.email || '',
          division: userProfile.division || squadToJoin.division || null,
          district: userProfile.district || squadToJoin.district || null,
          upazila: userProfile.upazila || squadToJoin.upazila || null,
          members: (squadToJoin.members || []).map((m: any) => ({
            userId: m.userId || m.uid || null,
            displayName: m.displayName || m.name || m.email?.split('@')[0] || 'Member',
            gameName: m.gameName || m.ingameName || m.displayName || m.name || m.email?.split('@')[0] || 'Member',
            email: m.email || '',
            photoURL: m.photoURL || m.photoUrl || m.avatarUrl || null,
            role: m.role || (m.isCaptain ? 'leader' : 'member'),
            isCaptain: m.isCaptain || m.role === 'leader',
            joinedAt: m.joinedAt || new Date().toISOString()
          })),
          joinedAt: new Date().toISOString()
        };

        const updatedSquads = [...joinedSquads, newSquadEntry];

        transaction.update(tourneyRef, {
          joinedSquads: updatedSquads,
          updatedAt: serverTimestamp()
        });
      });

      if (entryFee > 0) setTokensState(prev => Math.max(0, prev - entryFee));
      setPendingSquadJoinTourney(null);
      setSquadJoinSuccess(`Successfully joined tournament "${tournament.title}" with squad "${squadToJoin.name}"!`);
      // Take user back to the global tournament screen after joining
      setActiveTab('tournaments');
    } catch (err: any) {
      console.warn("Validation notice during squad tournament join:", err.message);
      setSquadJoinError(err.message || 'Failed to join tournament. Please try again.');
    } finally {
      setIsJoiningSquadTourney(false);
    }
  };
  const [replacePlayerModal, setReplacePlayerModal] = useState<{
    isOpen: boolean;
    teamId: string;
    oldMemberIdentifier: string;
    oldMemberName: string;
  } | null>(null);
  const [replaceNewIdInput, setReplaceNewIdInput] = useState("");
  const [isReplacingPlayer, setIsReplacingPlayer] = useState(false);
  const [replaceIdStatus, setReplaceIdStatus] = useState<"idle" | "checking" | "verified" | "not_found" | "self_id" | "already_member">("idle");
  const [replaceVerifiedUser, setReplaceVerifiedUser] = useState<any | null>(null);

  useEffect(() => {
    if (!replacePlayerModal || !replacePlayerModal.isOpen) {
      setReplaceIdStatus("idle");
      setReplaceVerifiedUser(null);
      return;
    }

    const cleanId = replaceNewIdInput.trim();
    if (!cleanId || cleanId.length < 3) {
      setReplaceIdStatus("idle");
      setReplaceVerifiedUser(null);
      return;
    }

    const captainPlayvearId = (userProfile?.playvearId || "").trim();
    if (cleanId === captainPlayvearId) {
      setReplaceIdStatus("self_id");
      setReplaceVerifiedUser(null);
      return;
    }

    const currentMembers = userTeam?.members || [];
    const isAlreadyInTeam = currentMembers.some((m: any) => 
      (m.playvearId && m.playvearId.trim() === cleanId) || 
      (m.email && m.email.trim().toLowerCase() === cleanId.toLowerCase())
    );
    if (isAlreadyInTeam) {
      setReplaceIdStatus("already_member");
      setReplaceVerifiedUser(null);
      return;
    }

    let isMounted = true;
    setReplaceIdStatus("checking");

    const timer = setTimeout(async () => {
      try {
        const usersCol = collection(db, "users");
        const q = query(usersCol, where("playvearId", "==", cleanId));
        const qSnap = await getDocs(q);

        let foundData: any = null;
        if (!qSnap.empty) {
          foundData = { id: qSnap.docs[0].id, data: qSnap.docs[0].data() };
        }

        if (!isMounted) return;

        if (foundData) {
          setReplaceIdStatus("verified");
          setReplaceVerifiedUser(foundData.data);
        } else {
          setReplaceIdStatus("not_found");
          setReplaceVerifiedUser(null);
        }
      } catch (err) {
        console.error("Error checking replace PlayVear ID in real-time:", err);
        if (isMounted) {
          setReplaceIdStatus("not_found");
          setReplaceVerifiedUser(null);
        }
      }
    }, 200);

    return () => {
      isMounted = false;
      clearTimeout(timer);
    };
  }, [replaceNewIdInput, replacePlayerModal, user, userTeam, userProfile]);
  const [teamLoading, setTeamLoading] = useState(false);
  const [pendingInvitations, setPendingInvitations] = useState<any[]>([]);
  const [generalNotifications, setGeneralNotifications] = useState<any[]>([]);
  const [showNotificationsDropdown, setShowNotificationsDropdown] = useState(false);
  const [showPlayerSupportModal, setShowPlayerSupportModal] = useState(false);
  const [playerSupportUnreadCount, setPlayerSupportUnreadCount] = useState(0);
  const notificationsDropdownHomeRef = useRef<HTMLDivElement>(null);
  const notificationsDropdownProfileRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!userProfile?.userId && !user?.uid) return;
    const currentUid = userProfile?.userId || user?.uid;
    const q = query(
      collection(db, 'admin_messages'),
      where('senderId', '==', currentUid)
    );
    const unsub = onSnapshot(q, (snap) => {
      let unread = 0;
      snap.docs.forEach((docSnap) => {
        const data = docSnap.data();
        if (data.status === 'replied') {
          unread++;
        }
      });
      setPlayerSupportUnreadCount(unread);
    });
    return () => unsub();
  }, [userProfile?.userId, user?.uid]);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      const isOutsideHome = notificationsDropdownHomeRef.current ? !notificationsDropdownHomeRef.current.contains(event.target as Node) : true;
      const isOutsideProfile = notificationsDropdownProfileRef.current ? !notificationsDropdownProfileRef.current.contains(event.target as Node) : true;
      
      if (isOutsideHome && isOutsideProfile) {
        setShowNotificationsDropdown(false);
      }
    }
    
    if (showNotificationsDropdown) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showNotificationsDropdown]);

  
  // Create / Edit Team form states
  const [teamFormName, setTeamFormName] = useState('');
  const [teamNameCheckStatus, setTeamNameCheckStatus] = useState<'idle' | 'checking' | 'available' | 'taken'>('idle');
  const [teamFormCoverUrl, setTeamFormCoverUrl] = useState('');
  const [isUploadingCover, setIsUploadingCover] = useState(false);
  const [coverUploadError, setCoverUploadError] = useState<string | null>(null);
  const [coverUploadSuccess, setCoverUploadSuccess] = useState<string | null>(null);
  const [isUpdatingExistingCoverTeamId, setIsUpdatingExistingCoverTeamId] = useState<string | null>(null);
  const [openCoverOptionsTeamId, setOpenCoverOptionsTeamId] = useState<string | null>(null);
  const [showAiPromptTeamId, setShowAiPromptTeamId] = useState<string | null>(null);
  const [existingCoverUpdateError, setExistingCoverUpdateError] = useState<string | null>(null);
  const [existingCoverUpdateSuccess, setExistingCoverUpdateSuccess] = useState<string | null>(null);
  const [teamFormInvites, setTeamFormInvites] = useState<string[]>(['', '', '']); // 3 friend emails slot max for 4-player squad
  const [inviteStatuses, setInviteStatuses] = useState<
    Array<{ status: 'idle' | 'checking' | 'found' | 'not_found' | 'self' | 'duplicate'; name?: string }>
  >([
    { status: 'idle' },
    { status: 'idle' },
    { status: 'idle' }
  ]);

  useEffect(() => {
    if (!user) return;
    let isMounted = true;
    const timer = setTimeout(async () => {
      const leaderPlayvearId = (userProfile?.playvearId || '').trim();
      const currentInvites = teamFormInvites.map(e => e.trim());
      const nextStatuses: Array<{ status: 'idle' | 'checking' | 'found' | 'not_found' | 'self' | 'duplicate'; name?: string }> = [];

      for (let i = 0; i < currentInvites.length; i++) {
        const playvearId = currentInvites[i];
        if (!playvearId) {
          nextStatuses[i] = { status: 'idle' };
        } else if (playvearId === leaderPlayvearId) {
          nextStatuses[i] = { status: 'self' };
        } else if (currentInvites.slice(0, i).includes(playvearId)) {
          nextStatuses[i] = { status: 'duplicate' };
        } else if (playvearId.length < 3) {
          nextStatuses[i] = { status: 'not_found' };
        } else {
          nextStatuses[i] = { status: 'checking' };
        }
      }

      if (!isMounted) return;
      setInviteStatuses([...nextStatuses]);

      for (let i = 0; i < currentInvites.length; i++) {
        if (nextStatuses[i]?.status !== 'checking') continue;

        const playvearId = currentInvites[i];
        try {
          const usersCol = collection(db, 'users');
          const q = query(usersCol, where('playvearId', '==', playvearId));
          const qSnap = await getDocs(q);

          if (!isMounted) return;

          if (!qSnap.empty) {
            const uData = qSnap.docs[0].data();
            const displayName = uData.displayName || uData.gameName || uData.name || 'Player';
            nextStatuses[i] = { status: 'found', name: displayName };
          } else {
            nextStatuses[i] = { status: 'not_found' };
          }
        } catch (err) {
          console.error("Error verifying PlayVear ID in database:", err);
          if (isMounted) {
            nextStatuses[i] = { status: 'not_found' };
          }
        }

        if (isMounted) {
          setInviteStatuses([...nextStatuses]);
        }
      }
    }, 400);

    return () => {
      isMounted = false;
      clearTimeout(timer);
    };
  }, [teamFormInvites, user, userProfile]);

  const verifiedInviteCount = useMemo(() => {
    return inviteStatuses.filter(s => s.status === 'found').length;
  }, [inviteStatuses]);

  const isAll3InvitesVerified = verifiedInviteCount === 3;
  const [isSavingTeam, setIsSavingTeam] = useState(false);

  // Debounced check for unique team name
  useEffect(() => {
    let isMounted = true;
    const trimmedName = teamFormName.trim();
    if (!trimmedName) {
      setTeamNameCheckStatus('idle');
      return;
    }

    setTeamNameCheckStatus('checking');

    const timer = setTimeout(async () => {
      try {
        const teamsSnap = await getDocs(collection(db, 'teams'));
        if (!isMounted) return;

        const isTaken = teamsSnap.docs.some(doc => {
          const tData = doc.data();
          const isOwnTeam = doc.id === user?.uid;
          if (isOwnTeam) return false;
          return tData.name && tData.name.trim().toLowerCase() === trimmedName.toLowerCase();
        });

        if (isMounted) {
          setTeamNameCheckStatus(isTaken ? 'taken' : 'available');
        }
      } catch (err) {
        console.error("Error checking squad name uniqueness:", err);
        if (isMounted) {
          setTeamNameCheckStatus('idle');
        }
      }
    }, 400);

    return () => {
      isMounted = false;
      clearTimeout(timer);
    };
  }, [teamFormName, user]);

