  // Auth and Profile sync
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);
      setError(null);
      
      if (currentUser) {
        // OPTIMISTIC UI: Load from localStorage instantly to bypass loading screen
        let hasCached = false;
        try {
          const cachedProfileStr = localStorage.getItem(`vortex_user_profile_${currentUser.uid}`);
          const cachedTokensStr = localStorage.getItem(`vortex_tokens_${currentUser.uid}`);
          if (cachedProfileStr) {
            setUserProfile(JSON.parse(cachedProfileStr));
            if (cachedTokensStr) setTokensState(Number(cachedTokensStr));
            hasCached = true;
            // Instantly clear loading states so page renders fast!
            setDbLoading(false);
            setSigningIn(false);
            setAuthLoading(false);
          }
        } catch(e) {}

        if (!hasCached) {
          setDbLoading(true);
        }

        let userDocRef = doc(db, 'users', currentUser.uid);
        
        try {
          // Timeout after 15 seconds to ensure user is never stuck
          const fetchPromise = getDoc(userDocRef);
          const timeoutPromise = new Promise<never>((_, reject) =>
            setTimeout(() => reject(new Error('Firestore read timeout')), 15000)
          );
          
          let userSnap = await Promise.race([fetchPromise, timeoutPromise]) as any;
          
          // Lookup by email or linkedUid if document was not found directly by UID
          if (!userSnap.exists() && currentUser.email) {
            const cleanEmail = currentUser.email.toLowerCase().trim();
            const emailQ = query(collection(db, 'users'), where('email', '==', cleanEmail));
            const emailQSnap = await getDocs(emailQ);
            if (!emailQSnap.empty) {
              userDocRef = emailQSnap.docs[0].ref;
              userSnap = emailQSnap.docs[0];
            } else {
              const linkedQ = query(collection(db, 'users'), where('linkedUid', '==', currentUser.uid));
              const linkedQSnap = await getDocs(linkedQ);
              if (!linkedQSnap.empty) {
                userDocRef = linkedQSnap.docs[0].ref;
                userSnap = linkedQSnap.docs[0];
              }
            }
          }
          
          if (!userSnap.exists()) {
            // Profile does not exist, create a new one
            
            // Generate next sequential PlayVear ID atomically (4001, 4002, 4003, ...)
            const generatedPlayvearId = await getNextSequentialPlayvearId();
            
            const isUserAdmin = currentUser.email === 'vortexesports150@gmail.com';
            const newProfile: UserProfile = {
              userId: currentUser.uid,
              playvearId: generatedPlayvearId,
              email: currentUser.email || '',
              displayName: currentUser.displayName || 'Gamer ' + currentUser.uid.substring(0, 5),
              fullName: currentUser.displayName || '',
              photoURL: currentUser.photoURL || null,
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString(),
              role: isUserAdmin ? 'admin' : 'user',
              health: 10, exp: 0,
              stars: 0,
              level: 1,
              economyScore: selectedGame === 'freefire' ? (3200 + Math.floor(Math.random() * 200)) : selectedGame === 'pubg' ? (1950 + Math.floor(Math.random() * 200)) : (850 + Math.floor(Math.random() * 200)),
            };

            setUserProfile(newProfile);
            setTokensState(150);
            try {
              localStorage.setItem(`vortex_user_profile_${currentUser.uid}`, JSON.stringify(newProfile));
              localStorage.setItem(`vortex_tokens_${currentUser.uid}`, '150');
            } catch (e) {
              console.error(e);
            }

            // Create doc in background
            setDoc(userDocRef, {
              userId: newProfile.userId,
              playvearId: newProfile.playvearId,
              email: newProfile.email,
              displayName: newProfile.displayName,
              fullName: newProfile.fullName || '',
              photoURL: newProfile.photoURL,
              createdAt: serverTimestamp(),
              updatedAt: serverTimestamp(),
              role: newProfile.role,
              tokens: 150,
              health: 10, exp: 0,
              stars: 0,
              level: 1,
              economyScore: newProfile.economyScore,
            }).catch(e => console.warn('Background profile create error:', e));

          } else {
            // Document exists
            const data = userSnap.data();

            // Check if account login email was updated and user is attempting login with old email
            if (data && data.email && currentUser.email && data.email.toLowerCase() !== currentUser.email.toLowerCase()) {
              await signOut(auth);
              setUser(null);
              setUserProfile(null);
              setError(`⚠️ LOGIN DENIED: The login Gmail for this account was changed to ${data.email}. You cannot log in using ${currentUser.email} anymore. Please sign in using ${data.email}.`);
              setDbLoading(false);
              setSigningIn(false);
              setAuthLoading(false);
              return;
            }

            // Check if account has been deactivated
            if (data && (data.accountDisabled || data.migratedToUid)) {
              const transferredTo = data.newEmail || 'your new Gmail account';
              await signOut(auth);
              setUser(null);
              setUserProfile(null);
              setError(`⚠️ LOGIN DENIED: This Google account is deactivated because login access was transferred to ${transferredTo}. Please sign in using your new Google account.`);
              setDbLoading(false);
              setSigningIn(false);
              setAuthLoading(false);
              return;
            }

            const isUserAdmin = currentUser.email === 'vortexesports150@gmail.com';
            
            // Auto update role to admin if email matches
            if (isUserAdmin && data.role !== 'admin') {
              updateDoc(userDocRef, { role: 'admin' }).catch(e => console.warn(e));
              data.role = 'admin';
            }

            if (data.selectedGame && (data.selectedGame === 'freefire' || data.selectedGame === 'pubg' || data.selectedGame === 'ludo')) {
              setSelectedGame(data.selectedGame);
            }

            const profileToCache: UserProfile = {
              userId: data.userId || currentUser.uid,
              playvearId: data.playvearId || "",
              email: data.email || currentUser.email || '',
              displayName: data.displayName || data.fullName || currentUser.displayName || 'Gamer',
              fullName: data.fullName || data.displayName || currentUser.displayName || '',
              name: data.name || data.fullName || '',
              photoURL: data.photoURL || currentUser.photoURL || null,
              createdAt: data.createdAt?.toDate?.()?.toISOString() || new Date().toISOString(),
              updatedAt: data.updatedAt?.toDate?.()?.toISOString() || new Date().toISOString(),
              role: (isUserAdmin ? 'admin' : (data.role || 'user')) as 'user' | 'admin',
              gameStats: data.gameStats || null,
              soloStats: data.soloStats || null,
              squadStats: data.squadStats || null,
              squadCsStats: data.squadCsStats || null,
              duoStats: data.duoStats || null,
              gmStats: data.gmStats || null,
              top48Stats: data.top48Stats || null,
              stats: data.stats || null,
              health: typeof data.health === 'number' ? data.health : 10,
              stars: typeof data.stars === 'number' ? data.stars : 0,
              level: typeof data.level === 'number' ? data.level : 1, 
              exp: typeof data.exp === 'number' ? data.exp : 0,
              economyScore: typeof data.economyScore === 'number' ? data.economyScore : 1,
              gamingUid: data.gamingUid || "",
              gameName: data.gameName || "",
              mobile: data.mobile || "",
              country: data.country || "Bangladesh",
              state: data.state || "",
              city: data.city || "",
              division: data.division || "",
              district: data.district || "",
              upazila: data.upazila || "",
            };

            // Fix for existing users missing or having non-numeric PlayVear ID
            if (!profileToCache.playvearId || !isValidNumericPlayvearId(profileToCache.playvearId)) {
              (async () => {
                const generatedId = await ensureSingleUserPlayvearId(userDocRef.id, profileToCache.playvearId);
                profileToCache.playvearId = generatedId;
                setUserProfile(prev => prev ? { ...prev, playvearId: generatedId } : { ...profileToCache, playvearId: generatedId });
              })();
            }

            setUserProfile(profileToCache);
            let finalTokens = 50;
            if (typeof data.tokens === 'number') {
              finalTokens = data.tokens;
              setTokensState(data.tokens);
            } else {
              setTokensState(50);
            }
            try {
              localStorage.setItem(`vortex_user_profile_${currentUser.uid}`, JSON.stringify(profileToCache));
              localStorage.setItem(`vortex_tokens_${currentUser.uid}`, String(finalTokens));
            } catch (e) {
              console.error(e);
            }
          }
          setOfflineMode(false);
        } catch (err) {
          console.warn('Could not connect to database or read timed out, using profile cache/fallback:', err);
          
          if (!hasCached) {
            const isUserAdmin = currentUser.email === 'vortexesports150@gmail.com';
            const fallbackProfile: UserProfile = {
              userId: currentUser.uid,
              email: currentUser.email || '',
              displayName: currentUser.displayName || 'Gamer ' + currentUser.uid.substring(0, 5),
              photoURL: currentUser.photoURL || null,
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString(),
              role: isUserAdmin ? 'admin' : 'user',
              economyScore: 100,
            };
            setUserProfile(fallbackProfile);
            setTokensState(150);
          }
          setOfflineMode(true);
        } finally {
          setDbLoading(false);
          setSigningIn(false);
          setAuthLoading(false);
        }
      } else {
        setUserProfile(null);
        setSigningIn(false);
        setAuthLoading(false);
      }
    });

    return () => unsubscribe();
  }, []);

  // Real-time listen for Team Invitations and User's Team
  useEffect(() => {
    if (!user) {
      setUserTeam(null);
      setPendingInvitations([]);
      return;
    }
    
    const emailToSearch = user.email?.toLowerCase() || '';
    
    // 1. Listen for pending invitations
    const invitationsQuery = query(
      collection(db, 'team_invitations'),
      where('recipientEmail', '==', emailToSearch),
      where('status', '==', 'pending')
    );
    const unsubInvitations = onSnapshot(invitationsQuery, (snap) => {
      const invitesList = snap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setPendingInvitations(invitesList);
    }, (err) => {
      console.error("Error listening to invitations:", err);
    });
    
    // 2. Listen for the user's team where user's email is in memberEmails
    const teamsQuery = query(
      collection(db, 'teams'),
      where('memberEmails', 'array-contains', emailToSearch)
    );
    
    const unsubTeams = onSnapshot(teamsQuery, (snap) => {
      if (!snap.empty) {
        const teams = snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as any));
        setUserTeams(teams);
        const created = teams.find(t => t.leaderId === user.uid || t.leaderEmail?.toLowerCase() === emailToSearch);
        setUserTeam(created || teams[0]);
      } else {
        setUserTeams([]);
        setUserTeam(null);
      }
    }, (err) => {
      console.error("Error listening to user team:", err);
    });
    
    // 3. Listen for general notifications
    const notifsQuery = query(
      collection(db, 'users', user.uid, 'notifications'),
      orderBy('createdAt', 'desc'),
      limit(20)
    );
    let isInitialNotifLoad = true;
    const unsubNotifications = onSnapshot(notifsQuery, (snap) => {
      const notifsList = snap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      
      if (!isInitialNotifLoad) {
        snap.docChanges().forEach((change) => {
          if (change.type === 'added') {
            const data = change.doc.data();
            triggerDevicePushNotification(data.title || 'PlayVear Notification', {
              body: data.message || data.text || 'You have a new update in PlayVear.',
              tag: change.doc.id
            });
          }
        });
      }
      isInitialNotifLoad = false;
      setGeneralNotifications(notifsList);
    }, (err) => {
      console.error("Error listening to notifications:", err);
    });

    return () => {
      unsubInvitations();
      unsubTeams();
      unsubNotifications();
    };
  }, [user]);

