  // Compress, crop to 1:1, downscale safely to keep file size optimized under 20 kb
  const handleUploadAndCompressAvatar = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!user) {
      triggerAvatarError("You must be logged in to upload a profile picture.");
      return;
    }

    setIsUploadingAvatar(true);
    setAvatarError(null);
    setAvatarSuccess(null);
    window.dispatchEvent(new CustomEvent('vortex-img-process', { detail: { processing: true, message: 'COMPRESSING PROFILE PHOTO' } }));

    const reader = new FileReader();
    reader.onload = (e) => {
      const dataUrl = e.target?.result as string;
      if (!dataUrl) {
        setIsUploadingAvatar(false);
        triggerAvatarError("Could not read local file.");
        window.dispatchEvent(new CustomEvent('vortex-img-process', { detail: { processing: false } }));
        return;
      }

      const img = new Image();
      img.onload = async () => {
        try {
          const canvas = document.createElement('canvas');
          const minDim = Math.min(img.width, img.height);
          const sx = (img.width - minDim) / 2;
          const sy = (img.height - minDim) / 2;

          let targetSize = 250;
          let targetQuality = 0.85;
          let finalDataUrl = '';

          // Interactive size reducer loop to guarantee data URL size is kept optimized strictly under 20KB
          while (targetSize >= 50) {
            canvas.width = targetSize;
            canvas.height = targetSize;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.imageSmoothingEnabled = true;
              ctx.imageSmoothingQuality = 'high';
              ctx.drawImage(img, sx, sy, minDim, minDim, 0, 0, targetSize, targetSize);
            }
            finalDataUrl = canvas.toDataURL('image/jpeg', targetQuality);
            
            const currentKb = (finalDataUrl.length * 0.75) / 1024;
            if (currentKb <= 20.0) {
              break;
            }
            targetSize -= 15;
            targetQuality -= 0.05;
            if (targetQuality < 0.35) {
              targetQuality = 0.35;
            }
          }

          // Safe fallback to guarantee image size is strictly under 20KB
          if (((finalDataUrl.length * 0.75) / 1024) > 20.0) {
            canvas.width = 80;
            canvas.height = 80;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, sx, sy, minDim, minDim, 0, 0, 80, 80);
            }
            finalDataUrl = canvas.toDataURL('image/jpeg', 0.50);
          }

          // Calculate approximate KB for display in UI
          const sizeInKb = (finalDataUrl.length * 0.75) / 1024;
          console.log(`Image compressed successfully: ${sizeInKb.toFixed(2)} KB, size: ${canvas.width}x${canvas.height}`);

          // Upload to ImgBB (Primary) with Firebase Storage fallback (Secondary)
          let avatarUrlToSave = '';
          try {
            // 1. Primary: Upload to ImgBB with specific category
            avatarUrlToSave = await uploadScreenshotToImgBB(finalDataUrl, 'profile_picture');
          } catch (uploadErr) {
            console.warn("ImgBB upload failed for player avatar, falling back to Firebase Storage...", uploadErr);
            try {
              // 2. Secondary: Upload to Firebase Cloud Storage
              const storageRef = ref(storage, `avatars/${user.uid}_${Date.now()}.jpg`);
              await uploadString(storageRef, finalDataUrl, 'data_url');
              avatarUrlToSave = await getDownloadURL(storageRef);
            } catch (fbErr) {
              console.warn("Firebase Storage fallback also failed, using base64 dataUrl...", fbErr);
              // 3. Ultimate Fallback: Base64 dataUrl
              avatarUrlToSave = finalDataUrl;
            }
          }

          // Update local profile state
          let updatedProfile: UserProfile | null = null;
          setUserProfile(prev => {
            if (!prev) return null;
            updatedProfile = {
              ...prev,
              photoURL: avatarUrlToSave,
              updatedAt: new Date().toISOString()
            };
            return updatedProfile;
          });

          // Store in Local Device Storage
          try {
            if (updatedProfile) {
              localStorage.setItem(`vortex_user_profile_${user.uid}`, JSON.stringify(updatedProfile));
            }
          } catch (storageErr) {
            console.error('Storage Cache Fail:', storageErr);
          }

          // Put to Cloud Firestore database and update Firebase Auth profile
          if (!offlineMode) {
            const userDocRef = doc(db, 'users', user.uid);
            
            // Also update squad captain photo if squad exists
            const squadUpdate: any = {};
            if (updatedProfile && (updatedProfile as any).squad?.members?.length) {
              const sqMembers = (updatedProfile as any).squad.members.map((m: any) => {
                if (m.userId === user.uid || m.isCaptain || m.email?.toLowerCase() === user.email?.toLowerCase()) {
                  return { ...m, photoURL: avatarUrlToSave };
                }
                return m;
              });
              squadUpdate.squad = {
                ...(updatedProfile as any).squad,
                members: sqMembers
              };
            }

            await updateDoc(userDocRef, {
              photoURL: avatarUrlToSave,
              ...squadUpdate,
              updatedAt: serverTimestamp()
            });

            // Update Firebase Auth user profile object
            try {
              if (auth.currentUser) {
                await updateProfile(auth.currentUser, {
                  photoURL: avatarUrlToSave
                });
              }
            } catch (authErr) {
              console.warn("Auth user photo update notice:", authErr);
            }

            // Also update user's team member avatar in teams collection if currently in a team
            if (userTeam && userTeam.id && Array.isArray(userTeam.members)) {
              try {
                const teamDocRef = doc(db, 'teams', userTeam.id);
                const updatedTeamMembers = userTeam.members.map((m: any) => {
                  if (m.userId === user.uid || (m.email && user.email && m.email.toLowerCase() === user.email.toLowerCase())) {
                    return { ...m, photoURL: avatarUrlToSave };
                  }
                  return m;
                });
                await updateDoc(teamDocRef, {
                  members: updatedTeamMembers,
                  ...(userTeam.leaderId === user.uid ? { leaderPhoto: avatarUrlToSave } : {}),
                  updatedAt: serverTimestamp()
                });
                setUserTeam((prevTeam: any) => prevTeam ? {
                  ...prevTeam,
                  members: updatedTeamMembers,
                  ...(prevTeam.leaderId === user.uid ? { leaderPhoto: avatarUrlToSave } : {})
                } : null);
              } catch (teamErr) {
                console.warn("Could not sync avatar to team doc:", teamErr);
              }
            }
          }

          // Broadcast avatar update event across the app
          window.dispatchEvent(new CustomEvent('vortex-profile-updated', { 
            detail: { userId: user.uid, photoURL: avatarUrlToSave } 
          }));

          triggerAvatarSuccess(`Avatar optimized (${sizeInKb.toFixed(1)} KB) & saved!`);
        } catch (err: any) {
          console.error("Avatar compress & save error:", err);
          triggerAvatarError(err?.message || "Failed to update profile picture.");
          try {
            handleFirestoreError(err, OperationType.WRITE, `users/${user.uid}`);
          } catch (e) {
            // Error logged
          }
        } finally {
          setIsUploadingAvatar(false);
          window.dispatchEvent(new CustomEvent('vortex-img-process', { detail: { processing: false } }));
        }
      };

      img.onerror = () => {
        setIsUploadingAvatar(false);
        triggerAvatarError("Invalid image file format.");
        window.dispatchEvent(new CustomEvent('vortex-img-process', { detail: { processing: false } }));
      };

      img.src = dataUrl;
    };

    reader.onerror = () => {
      setIsUploadingAvatar(false);
      triggerAvatarError("Failed to load file.");
      window.dispatchEvent(new CustomEvent('vortex-img-process', { detail: { processing: false } }));
    };

    reader.readAsDataURL(file);
  };

  // Compress, crop to 16:9, downscale safely to keep team cover image size strictly under 70 KB to save database storage costs
  const handleUploadAndCompressTeamCover = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!user) {
      setCoverUploadError("You must be logged in to upload a team cover.");
      return;
    }

    setIsUploadingCover(true);
    setCoverUploadError(null);
    setCoverUploadSuccess(null);
    window.dispatchEvent(new CustomEvent('vortex-img-process', { detail: { processing: true, message: 'COMPRESSING TEAM COVER' } }));

    const reader = new FileReader();
    reader.onload = (e) => {
      const dataUrl = e.target?.result as string;
      if (!dataUrl) {
        setIsUploadingCover(false);
        setCoverUploadError("Could not read local file.");
        window.dispatchEvent(new CustomEvent('vortex-img-process', { detail: { processing: false } }));
        return;
      }

      const img = new Image();
      img.onload = async () => {
        try {
          const canvas = document.createElement('canvas');
          const imgWidth = img.width;
          const imgHeight = img.height;

          // Target 16:9 aspect ratio center crop
          const targetAspect = 16 / 9;
          const currentAspect = imgWidth / imgHeight;

          let sx = 0, sy = 0, sWidth = imgWidth, sHeight = imgHeight;
          if (currentAspect > targetAspect) {
            // Image is wider, crop sides
            sWidth = imgHeight * targetAspect;
            sx = (imgWidth - sWidth) / 2;
          } else {
            // Image is taller, crop top/bottom
            sHeight = imgWidth / targetAspect;
            sy = (imgHeight - sHeight) / 2;
          }

          let targetWidth = 800;
          let targetQuality = 0.85;
          let finalDataUrl = '';

          // Iterate to keep size strictly under 60 KB
          while (targetWidth >= 320) {
            canvas.width = targetWidth;
            canvas.height = Math.round(targetWidth / targetAspect);
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.imageSmoothingEnabled = true;
              ctx.imageSmoothingQuality = 'high';
              ctx.drawImage(img, sx, sy, sWidth, sHeight, 0, 0, canvas.width, canvas.height);
            }
            finalDataUrl = canvas.toDataURL('image/jpeg', targetQuality);
            const sizeInKb = (finalDataUrl.length * 0.75) / 1024;
            if (sizeInKb <= 60.0) {
              break;
            }
            targetWidth -= 80;
            targetQuality -= 0.1;
            if (targetQuality < 0.3) {
              targetQuality = 0.3;
            }
          }

          // Strict fallback
          if (((finalDataUrl.length * 0.75) / 1024) > 60.0) {
            canvas.width = 320;
            canvas.height = 180;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, sx, sy, sWidth, sHeight, 0, 0, 320, 180);
            }
            finalDataUrl = canvas.toDataURL('image/jpeg', 0.4);
          }

          // Upload to ImgBB (with Firebase Storage fallback if ImgBB is unreachable)
          let coverUrlToSave = '';
          try {
            coverUrlToSave = await uploadScreenshotToImgBB(finalDataUrl, 'cover_photo');
          } catch (uploadErr) {
            console.warn("ImgBB upload failed for squad cover, falling back to Firebase Storage", uploadErr);
            const storageRef = ref(storage, `team_covers/${user.uid}_${Date.now()}.jpg`);
            await uploadString(storageRef, finalDataUrl, 'data_url');
            coverUrlToSave = await getDownloadURL(storageRef);
          }

          const finalSizeKb = (finalDataUrl.length * 0.75) / 1024;
          if (isEditingTeam) {
            setEditTeamCoverUrl(coverUrlToSave);
          } else {
            setTeamFormCoverUrl(coverUrlToSave);
          }
        } catch (err) {
          console.error("Error compressing cover:", err);
          setCoverUploadError("Failed to compress team cover image.");
        } finally {
          setIsUploadingCover(false);
          window.dispatchEvent(new CustomEvent('vortex-img-process', { detail: { processing: false } }));
        }
      };

      img.onerror = () => {
        setIsUploadingCover(false);
        setCoverUploadError("Invalid image file format.");
        window.dispatchEvent(new CustomEvent('vortex-img-process', { detail: { processing: false } }));
      };

      img.src = dataUrl;
    };

    reader.onerror = () => {
      setIsUploadingCover(false);
      setCoverUploadError("Failed to read file from device.");
      window.dispatchEvent(new CustomEvent('vortex-img-process', { detail: { processing: false } }));
    };

    reader.readAsDataURL(file);
  };

