  const handleDisbandTeam = async (teamId: string) => {
    if (!confirm("Are you sure you want to disband this team? This action is permanent!")) return;
    try {
      await deleteDoc(doc(db, 'teams', teamId));
      
      // Also remove squad field from leader
      if (user) {
        await updateDoc(doc(db, 'users', user.uid), {
          squad: null
        });
      }
      alert("Team disbanded successfully.");
    } catch (err) {
      console.error("Error disbanding team:", err);
      alert("Failed to disband team.");
    }
  };

  const handleUpdateMemberCredentials = async (teamId: string, memberEmail: string, updatedGameName: string, updatedGamingUid: string) => {
    try {
      const teamRef = doc(db, 'teams', teamId);
      const teamSnap = await getDoc(teamRef);
      if (teamSnap.exists()) {
        const teamData = teamSnap.data();
        const membersList = [...(teamData.members || [])];
        const idx = membersList.findIndex(m => m.email?.toLowerCase() === memberEmail.toLowerCase());
        
        if (idx >= 0) {
          membersList[idx] = {
            ...membersList[idx],
            gameName: updatedGameName.trim(),
            gamingUid: updatedGamingUid.trim()
          };

          await updateDoc(teamRef, {
            members: membersList,
            updatedAt: new Date().toISOString()
          });

          // Also sync user profile if it's the current user updating their own
          if (user && memberEmail.toLowerCase() === user.email?.toLowerCase()) {
            await updateDoc(doc(db, 'users', user.uid), {
              gameName: updatedGameName.trim(),
              gamingUid: updatedGamingUid.trim()
            });
          }

          alert("Game Credentials updated successfully inside your Esports Squad!");
        }
      }
    } catch (err) {
      console.error("Error updating credentials:", err);
      alert("Failed to update credentials in team.");
    }
  };

  const handleReplaceTeamMember = async (teamId: string, oldMemberIdentifier: string, oldMemberName: string, directNewId?: string) => {
    if (!user) {
      alert("You must be logged in to replace squad members.");
      return;
    }
    const captainPlayvearId = (userProfile?.playvearId || "").trim();
    const isLeader = (userTeam?.leaderId && userTeam.leaderId === user.uid) || 
                     (userProfile?.playvearId && userTeam?.leaderPlayvearId && userTeam.leaderPlayvearId === userProfile.playvearId);
    if (!isLeader) {
      alert("Only the Captain can replace squad members.");
      return;
    }

    const cleanOldIdentifier = (oldMemberIdentifier || "").trim();
    if (!cleanOldIdentifier) {
      alert("Invalid member selected to replace.");
      return;
    }

    let newIdInput = directNewId;
    if (!newIdInput) {
      const prompted = prompt(`Enter registered player PlayVear ID to replace "${oldMemberName || oldMemberIdentifier}":`);
      if (prompted === null) return;
      newIdInput = prompted;
    }

    const newPlayvearId = newIdInput.trim();
    if (!newPlayvearId) {
      alert("PlayVear ID cannot be empty.");
      return;
    }

    if (newPlayvearId === captainPlayvearId) {
      alert("You cannot replace a squad member with your own Captain PlayVear ID.");
      return;
    }

    const currentMembers = userTeam.members || [];
    const isAlreadyMember = currentMembers.some((m: any) => 
      (m.playvearId && m.playvearId.trim() === newPlayvearId) || 
      (m.email && m.email.trim().toLowerCase() === newPlayvearId.toLowerCase())
    );
    if (isAlreadyMember) {
      alert(`The PlayVear ID "${newPlayvearId}" is already in your squad roster!`);
      return;
    }

    try {
      const usersCol = collection(db, "users");
      const q = query(usersCol, where("playvearId", "==", newPlayvearId));
      const qSnap = await getDocs(q);

      let foundDoc: any = null;
      if (!qSnap.empty) {
        foundDoc = { id: qSnap.docs[0].id, data: qSnap.docs[0].data() };
      }

      let newMemberObj: any = null;
      if (foundDoc) {
        const uData = foundDoc.data;
        newMemberObj = {
          userId: foundDoc.id,
          playvearId: newPlayvearId,
          email: uData.email || "",
          displayName: uData.displayName || uData.gameName || uData.name || `Player ${newPlayvearId}`,
          photoURL: uData.photoURL || uData.avatar || "",
          gameName: uData.gameName || "",
          gamingUid: uData.gamingUid || "",
          role: "member",
          status: "pending"
        };
      } else {
        alert(`The PlayVear ID "${newPlayvearId}" is not registered in PlayVear! All squad members must have a registered account.`);
        return;
      }

      // Update members list
      const updatedMembers = currentMembers.map((m: any) => {
        const mId = (m.playvearId || "").trim();
        const mEmail = (m.email || "").trim().toLowerCase();
        if (mId === cleanOldIdentifier || mEmail === cleanOldIdentifier.toLowerCase()) {
          return newMemberObj;
        }
        return m;
      });

      const updatedMemberEmails = (userTeam.memberEmails || []).filter((e: string) => (e || "").trim().toLowerCase() !== cleanOldIdentifier.toLowerCase());
      if (newMemberObj.email && !updatedMemberEmails.includes(newMemberObj.email)) {
        updatedMemberEmails.push(newMemberObj.email);
      }

      const teamRef = doc(db, "teams", teamId);
      await updateDoc(teamRef, {
        members: updatedMembers,
        memberEmails: updatedMemberEmails,
        updatedAt: new Date().toISOString()
      });

      // Delete any previous pending invitation for cleanOldIdentifier
      try {
        const oldInvQuery = query(
          collection(db, "team_invitations"),
          where("teamId", "==", teamId)
        );
        const oldInvSnap = await getDocs(oldInvQuery);
        oldInvSnap.forEach(async (invDoc) => {
          const invData = invDoc.data();
          if (invData.recipientPlayvearId === cleanOldIdentifier || invData.recipientEmail?.toLowerCase() === cleanOldIdentifier.toLowerCase()) {
            await deleteDoc(doc(db, "team_invitations", invDoc.id));
          }
        });
      } catch (invErr) {
        console.warn("Could not remove old invitation:", invErr);
      }

      // Create new pending invitation
      try {
        const invRef = doc(collection(db, "team_invitations"));
        await setDoc(invRef, {
          id: invRef.id,
          teamId: teamId,
          teamName: userTeam.name || "Esports Squad",
          senderId: user.uid,
          senderEmail: user.email?.toLowerCase() || "",
          senderName: userProfile?.displayName || user.displayName || "Captain",
          recipientPlayvearId: newPlayvearId,
          recipientEmail: newMemberObj.email,
          status: "pending",
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString()
        });

        if (newMemberObj.userId) {
          const notifRef = doc(collection(db, "users", newMemberObj.userId, "notifications"));
          await setDoc(notifRef, {
            id: notifRef.id,
            title: "Squad Player Invitation",
            message: `You have been added to squad "${userTeam.name || "Esports Squad"}" by Captain ${userProfile?.displayName || user.displayName || "Captain"} (PlayVear ID: ${captainPlayvearId}).`,
            type: "team_invite",
            createdAt: new Date().toISOString(),
            read: false
          });
        }
      } catch (invCreateErr) {
        console.warn("Could not create invitation record:", invCreateErr);
      }

      setUserTeam((prev: any) => prev ? {
        ...prev,
        members: updatedMembers,
        memberEmails: updatedMemberEmails
      } : prev);

      alert(`✅ Player replaced successfully! Invitation sent to PlayVear ID ${newPlayvearId}.`);
    } catch (err) {
      console.error("Error replacing squad member:", err);
      alert("Failed to replace squad member. Please try again.");
    }
  };

  // Real-time Active User Document Sync
