  const [isUploadingImage, setIsUploadingImage] = useState<string | null>(null);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, bannerType: 'small' | 'big', mode: 'new' | 'admin') => {
    const file = e.target.files?.[0];
    if (!file) return;

    const stateKey = `${mode}_${bannerType}`;
    setIsUploadingImage(stateKey);

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const maxDim = bannerType === 'small' ? 300 : 550;
        let width = img.width;
        let height = img.height;

        if (width > maxDim || height > maxDim) {
          if (width > height) {
            height = Math.round((height * maxDim) / width);
            width = maxDim;
          } else {
            width = Math.round((width * maxDim) / height);
            height = maxDim;
          }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          const compressedDataUrl = canvas.toDataURL('image/jpeg', 0.5);
          
          if (mode === 'new') {
            if (bannerType === 'small') setNewTourneySmallBanner(compressedDataUrl);
            else setNewTourneyBigBanner(compressedDataUrl);
          } else {
            if (bannerType === 'small') setAdminSmallBanner(compressedDataUrl);
            else setAdminBigBanner(compressedDataUrl);
          }
        }
        setIsUploadingImage(null);
      };
      img.onerror = () => {
        setIsUploadingImage(null);
        alert('Failed to load image. Please try a different file.');
      };
      if (event.target?.result) {
        img.src = event.target.result as string;
      }
    };
    reader.onerror = () => {
      setIsUploadingImage(null);
      alert('Error reading file. Please try again.');
    };
    reader.readAsDataURL(file);
  };

  const handleScreenshotUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploadingScreenshot(true);

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const maxDim = 1280;
        let width = img.width;
        let height = img.height;

        if (width > maxDim || height > maxDim) {
          if (width > height) {
            height = Math.round((height * maxDim) / width);
            width = maxDim;
          } else {
            width = Math.round((width * maxDim) / height);
            height = maxDim;
          }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          
          let quality = 0.7;
          let compressedDataUrl = canvas.toDataURL('image/jpeg', quality);
          
          while (compressedDataUrl.length > 150000 && quality > 0.1) {
            quality -= 0.15;
            compressedDataUrl = canvas.toDataURL('image/jpeg', quality);
          }
          
          if (compressedDataUrl.length > 150000) {
            let scale = 0.8;
            while (compressedDataUrl.length > 150000 && scale > 0.3) {
              const scaledWidth = Math.round(width * scale);
              const scaledHeight = Math.round(height * scale);
              canvas.width = scaledWidth;
              canvas.height = scaledHeight;
              const sCtx = canvas.getContext('2d');
              if (sCtx) {
                sCtx.drawImage(img, 0, 0, scaledWidth, scaledHeight);
                compressedDataUrl = canvas.toDataURL('image/jpeg', 0.5);
              }
              scale -= 0.15;
            }
          }
          
          uploadScreenshotToImgBB(compressedDataUrl, 'match_result_screenshots')
            .then((imgbbUrl) => {
              setAdminMatchScreenshot(imgbbUrl);
            })
            .catch((err) => {
              console.warn("ImgBB upload failed, falling back to local compressed image", err);
              setAdminMatchScreenshot(compressedDataUrl);
            })
            .finally(() => {
              setIsUploadingScreenshot(false);
            });
        } else {
          setIsUploadingScreenshot(false);
        }
      };
      img.onerror = () => {
        setIsUploadingScreenshot(false);
        alert('Failed to load image. Please try a different file.');
      };
      if (event.target?.result) {
        img.src = event.target.result as string;
      }
    };
    reader.onerror = () => {
      setIsUploadingScreenshot(false);
      alert('Failed to read the file.');
    };
    reader.readAsDataURL(file);
  };

