  const formatTimingString = (dateStr: string, timeStr: string) => {
    try {
      const [year, month, day] = dateStr.split('-').map(Number);
      const [hour, min] = timeStr.split(':').map(Number);
      const d = new Date(year, month - 1, day, hour, min);
      
      if (isNaN(d.getTime())) return `${dateStr} @ ${timeStr}`;

      const pm = hour >= 12;
      const hour12 = hour % 12 === 0 ? 12 : hour % 12;
      const minStr = min < 10 ? `0${min}` : min;
      const ampmStr = pm ? 'PM' : 'AM';
      
      const today = new Date();
      const isToday = d.toDateString() === today.toDateString();
      const tomorrow = new Date();
      tomorrow.setDate(tomorrow.getDate() + 1);
      const isTomorrow = d.toDateString() === tomorrow.toDateString();
      
      const dayLabel = isToday ? '' : isTomorrow ? 'Tomorrow' : d.toLocaleDateString([], { weekday: 'short', month: 'short', day: 'numeric' });
      const separator = dayLabel ? ' @ ' : '';
      return `${dayLabel}${separator}${hour12}:${minStr} ${ampmStr} (${dateStr})`;
    } catch (err) {
      return `${dateStr} @ ${timeStr}`;
    }
  };

