  const handleCreateTournament = async () => {
    try {
      let nextSeqNumber = 1;
      const counterDocRef = doc(db, 'system_config', 'match_counter');
      try {
        const counterSnap = await getDoc(counterDocRef);
        if (counterSnap.exists()) {
          const currentCount = counterSnap.data().totalMatchesCreated || 0;
          nextSeqNumber = currentCount + 1;
        } else {
          const totalExisting = ffTournaments.length + pubgTournaments.length + ludoTournaments.length;
          nextSeqNumber = totalExisting + 1;
        }
      } catch (e) {
        console.warn('Failed to read counter doc, using fallback count', e);
        nextSeqNumber = (ffTournaments.length + pubgTournaments.length + ludoTournaments.length) + 1;
      }

      // Save the updated counter
      try {
        await setDoc(counterDocRef, { totalMatchesCreated: nextSeqNumber }, { merge: true });
      } catch (e) {
        console.error('Failed to update counter doc', e);
      }

      const now = new Date();
      const yyyy = now.getFullYear();
      const mm = String(now.getMonth() + 1).padStart(2, '0');
      const dd = String(now.getDate()).padStart(2, '0');
      const hh = String(now.getHours()).padStart(2, '0');
      const min = String(now.getMinutes()).padStart(2, '0');
      const ss = String(now.getSeconds()).padStart(2, '0');
      const timePart = `${hh}${min}${ss}`;
      
      const gameIdPrefix = selectedGame === 'freefire' ? 'ff_' : selectedGame === 'pubg' ? 'pb_' : 'ld_';
      const generatedId = `${gameIdPrefix}${nextSeqNumber}${yyyy}${mm}${dd}${timePart}`;
      const formattedTime = formatTimingString(newTourneyDate, newTourneyTime);
      
      const titlePrefix = newTourneyTitle.trim() || 
        (selectedGame === 'freefire' 
          ? (newTourneyType === 'squad' ? 'FF BR Squad' : 'Free Fire Solo') 
          : selectedGame === 'pubg' 
            ? (newTourneyType === 'squad' ? 'PUBG Squad Battle' : 'PUBG Solo Battle') 
            : 'Ludo King 1v1');

      const slotCount = typeof newTourneyMaxPlayers === 'number' && newTourneyMaxPlayers > 0
        ? newTourneyMaxPlayers
        : (newTourneyType === 'squad' ? 12 : (selectedGame === 'freefire' ? 48 : selectedGame === 'pubg' ? 100 : 4));
      
      const initialPlayers: any[] = [];

      const newTourneyData = {
        id: generatedId,
        tournamentNumber: nextSeqNumber,
        title: titlePrefix,
        type: newTourneyType,
        maxPlayers: slotCount,
        perKill: Number(newTourneyPerKill),
        booyahPrize: Number(newTourneyBooyah),
        runnerUpPrize: Number(newTourneyRunnerUp),
        entryFee: Number(newTourneyEntryFee),
        map: newTourneyMap,
        time: formattedTime,
        startTimeISO: `${newTourneyDate}T${newTourneyTime}:00`,
        playerEligibly: 'No',
        minLevel: Number(newTourneyMinLevel),
        minHealth: Number(newTourneyMinHealth),
        minStars: Number(newTourneyMinStars),
        minEco: Number(newTourneyMinEco),
        joinedCount: 0,
        joinedPlayers: initialPlayers,
        status: 'Upcoming',
        isGrandmasterOnly: newTourneyGrandmasterOnly || (newTourneyType === 'top_48'),
        top48Deadline: (newTourneyType === 'top_48' && newTourneyTop48DeadlineDate && newTourneyTop48DeadlineTime) ? `${newTourneyTop48DeadlineDate}T${newTourneyTop48DeadlineTime}:00` : null,
        lockedTop48UserIds: null,
        smallBanner: newTourneySmallBanner.trim(),
        bigBanner: newTourneyBigBanner.trim(),
        absenceHealthPenalty: Number(newTourneyAbsenceHealthPenalty),
        absenceEconomyPenalty: Number(newTourneyAbsenceEconomyPenalty),
        zeroKillsHealthPenalty: Number(newTourneyZeroKillsHealthPenalty),
        zeroKillsEconomyPenalty: Number(newTourneyZeroKillsEconomyPenalty),
        perKillHealthBoost: Number(newTourneyPerKillHealthBoost),
        perKillEconomyBoost: Number(newTourneyPerKillEconomyBoost),
        booyahHealthBoost: Number(newTourneyBooyahHealthBoost),
        booyahEconomyBoost: Number(newTourneyBooyahEconomyBoost),
        runnerUpHealthBoost: Number(newTourneyRunnerUpHealthBoost),
        runnerUpEconomyBoost: Number(newTourneyRunnerUpEconomyBoost),
        updatedAt: new Date().toISOString()
      };
      
      const newDocRef = doc(db, 'tournaments_' + selectedGame, generatedId);
      const docPayload = {
        ...newTourneyData,
        gameCategory: selectedGame,
        updatedAt: serverTimestamp()
      };
      
      try {
        await setDoc(newDocRef, docPayload);
      } catch (err) {
        handleFirestoreError(err, OperationType.WRITE, `tournaments_${selectedGame}/${generatedId}`);
      }
      
      // Save duplicate record into match_history_results for searching & archival logs
      try {
        await setDoc(doc(db, 'match_history_results', generatedId), {
          ...docPayload,
          game: selectedGame,
          savedAt: new Date().toISOString()
        });
      } catch (historyErr) {
        console.warn('Silent error writing history doc:', historyErr);
      }
      
      await logAdminAction('CREATE_TOURNAMENT', `Hosted new tournament '${newTourneyData.title}' (Map: ${newTourneyData.map}) under ${selectedGame === 'freefire' ? 'Free Fire' : selectedGame === 'pubg' ? 'PUBG' : 'Ludo'}.`);

      setSelectedHomeTourneyId(generatedId);
      setShowCreateTourney(false);
      setShowAdminAddForm(false);
      resetNewTourneyForm();
      return generatedId;
    } catch (err) {
      console.error('Error hosting new tournament:', err);
      throw err;
    }
  };

  // Dynamic Game-based ID selection and default ID auto-synchronizer
