      snap.forEach(d => {
        const item = d.data() || {};
        const itemId = item.id || d.id;
        if (!seen.has(itemId)) {
          seen.add(itemId);
          list.push({ ...item, id: itemId, game: 'freefire' });
        }
      });
      list.sort((a, b) => String(b.id || '').localeCompare(String(a.id || '')));
      setFfTournaments(list);
