  const handleAddTokensToWallet = async () => {
    if (!walletAddModal.type) return;
    const amountVal = Number(walletAddAmount);
    if (isNaN(amountVal) || amountVal <= 0) {
      alert("Please enter a valid positive amount.");
      return;
    }

    if (walletAddModal.type === 'giveawayWallet') {
      const hasPerm = (user?.email?.trim().toLowerCase() === 'vortexesports150@gmail.com') || checkAdminPermission(user?.email, currentUserPermissions || userProfile?.permissions, 'add_giveaway_tokens');
      if (!hasPerm) {
        alert("Permission Denied: You do not have permission to add tokens to the Giveaway Wallet. Please request permission from the Super Administrator.");
        return;
      }
    }
    
    setWalletAddLoading(true);
    try {
      const walletRef = doc(db, 'system', 'wallets');
      const docSnap = await getDoc(walletRef);
      if (!docSnap.exists()) {
        await setDoc(walletRef, {
          adsWallet: 0,
          prizesWallet: 0,
          mainWallet: 0,
          receivedWallet: 0,
          giveawayWallet: 0
        });
      }
      
      const updateData: any = {};
      updateData[walletAddModal.type] = increment(amountVal);
      updateData[`${walletAddModal.type}Total`] = increment(amountVal);
      await updateDoc(walletRef, updateData);

      // Add to history
      await addDoc(collection(db, 'system', 'wallets', 'history'), {
        walletType: walletAddModal.type,
        amountAdded: amountVal,
        type: 'addition',
        reason: 'Admin Token Addition',
        addedBy: user?.uid,
        addedByEmail: user?.email,
        createdAt: serverTimestamp()
      });

      alert(`Successfully added ${amountVal} tokens to ${
        walletAddModal.type === 'adsWallet' ? 'System Ads Payout' : 
        walletAddModal.type === 'prizesWallet' ? 'Prizes Wallet' : 
        walletAddModal.type === 'mainWallet' ? 'Main Wallet' : 
        walletAddModal.type === 'upazilaLeagueWallet' ? 'Upazila League Wallet' : 
        walletAddModal.type === 'tournamentAdsWallet' ? 'Tournament Sponsor Ads' : 
        walletAddModal.type === 'giveawayWallet' ? 'YouTube Giveaway Wallet' :
        'Received Wallet'
      }.`);
      setWalletAddModal({isOpen: false, type: null});
      setWalletAddAmount('');
    } catch (err) {
      console.error(err);
      alert("Failed to add tokens.");
    } finally {
      setWalletAddLoading(false);
    }
  };

