                        const totalRunnerUp = Math.max(userProfile?.stats?.runnerUps || 0, (soloS.runnerUps || 0) + (squadS.runnerUps || 0) + (squadCsS.runnerUps || 0) + (gmS.runnerUps || 0) + (top48S.runnerUps || 0));

