                        const userEmail = user?.email?.toLowerCase();
                        const memberA = a.members?.find((m: any) => m.email?.toLowerCase() === userEmail);
                        const memberB = b.members?.find((m: any) => m.email?.toLowerCase() === userEmail);
                        const timeA = memberA?.joinedAt ? new Date(memberA.joinedAt).getTime() : (a.updatedAt ? new Date(a.updatedAt).getTime() : 0);
                        const timeB = memberB?.joinedAt ? new Date(memberB.joinedAt).getTime() : (b.updatedAt ? new Date(b.updatedAt).getTime() : 0);
                        return timeB - timeA;
