                        if (!inputRoomId.trim()) {
                          alert("Please enter a valid Room ID before taking the match live.");
                          return;
                        }
                        setIsStartingLive(true);
                        try {
                          // Update tournament in DB with Room ID, Password, and status 'Ongoing'
                          const matchRef = doc(db, 'tournaments_' + selectedGame, roomModalMatchId);
                          await updateDoc(matchRef, {
                            roomId: inputRoomId.trim(),
                            roomPass: inputRoomPass.trim(),
                            youtubeLiveUrl: inputYoutubeLink.trim(),
                            status: 'Ongoing',
                            updatedAt: serverTimestamp()
                          });

                          // Update local state
                          setAllDbTournaments(prev => prev.map(t => {
                            if (t.id === roomModalMatchId) {
                              return { ...t, roomId: inputRoomId.trim(), roomPass: inputRoomPass.trim(), youtubeLiveUrl: inputYoutubeLink.trim(), status: 'Ongoing' };
                            }
                            return t;
                          }));

                          setShowRoomModal(false);
                          setInputRoomId('');
                          setInputRoomPass('');
                          alert("Success! Match is now Live with Room ID and Password confirmed.");
                        } catch (err: any) {
                          console.error("Error taking match live with room details:", err);
                          alert("Failed to start match live: " + (err.message || err));
                        } finally {
                          setIsStartingLive(false);
                        }
